import { getPosts } from '@/lib/api';

// Set revalidation time to 1 hour (3600 seconds)
export const revalidate = 3600;

export default async function Home() {
  const posts = await getPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <strong>{post.title}</strong> by {post.author}
          </li>
        ))}
      </ul>
    </main>
  );
}

